// === Tab: Gem ===
class Gem {

	constructor(x, y, d, pt) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.r = d/2;
		this.pt = pt;
		this.init();
	}

	init() {
		this.first = false; // when true, bg of gem is white (nice, but flashes)

		// colors
		this.hueS = random(360); // hue start
		this.hueD = random(120, 210); // hue deviation
		this.hueO = random(15, 45) * Math.sign(random()-0.5); // hue offset (top part)

		// shape
		const f1 = random(0.3, 0.75);
		const f2 = random(f1 + 0.1, 0.95);
		const a1 = HALF_PI + f1 * PI;
		const a2 = HALF_PI + f2 * PI;
		this.pts = [];
		this.pts.push({x: 0, y: this.r});
		this.pts.push({x: + cos(a1) * this.r, y:  + sin(a1) * this.r});
		this.pts.push({x: + cos(a2) * this.r, y:  + sin(a2) * this.r});
		this.pts.push({x: - cos(a2) * this.r, y:  + sin(a2) * this.r});
		this.pts.push({x: - cos(a1) * this.r, y:  + sin(a1) * this.r});
	}

	draw() {
		push();
		rectMode(CENTER)
		colorMode(HSB);
		stroke("silver")
		strokeWeight(2);
		noFill();

		line(this.pt.x, this.pt.y, this.pt.x, this.pts[2].y + this.y);

		translate(this.x, this.y)



		const d = this.d;
		beginShape();
		for (const p of this.pts) vertex(p.x, p.y);
		endShape(CLOSE);

		stroke("rgba(255, 255, 255, 0.01)");

		// mask bottom part
		push();
		beginClip();
		beginShape();
		// for (const p of this.pts) vertex(p.x, p.y);
		vertex(this.pts[0].x, this.pts[0].y);
		vertex(this.pts[1].x, this.pts[1].y);
		vertex(this.pts[4].x, this.pts[4].y);
		endShape(CLOSE);
		endClip();
		this.overlays();
		pop();

		// mask upper part
		push();
		beginClip();
		beginShape();
		// for (const p of this.pts) vertex(p.x, p.y);
		vertex(this.pts[1].x, this.pts[1].y);
		vertex(this.pts[2].x, this.pts[2].y);
		vertex(this.pts[3].x, this.pts[3].y);
		vertex(this.pts[4].x, this.pts[4].y);
		endShape(CLOSE);
		endClip();
		this.overlays(this.hueO);
		pop();

		// lines
		strokeWeight(1.5);
		stroke("rgba(255, 255, 255, 0.015)");
		line(this.pts[1].x, this.pts[1].y, this.pts[4].x, this.pts[4].y);
		if (this.pts[2].x > this.pts[1].x) {			
			line(this.pts[2].x, this.pts[2].y, this.pts[2].x+(this.pts[2].x-this.pts[1].x), this.pts[1].y-1);
			line(this.pts[3].x, this.pts[3].y, this.pts[3].x-(this.pts[2].x-this.pts[1].x), this.pts[1].y-1);
		}

		this.first = false; // only 1st time white bg in overlays()

		pop();
	} // draw

	overlays(hueOff = 0) {
		const a = random(TWO_PI);
		var d = this.d;
		const r = random(this.r);
		const x = cos(a) * r;
		const y = sin(a) * r;
		const v = createVector(x, y).rotate(HALF_PI);

		push()
		if (this.first) {
			fill("white");
			circle(0,0,this.d)
		}
		strokeWeight(1);
		translate(x, y)
		rotate(v.heading())
		let hue = this.hueS + random(this.hueD/4, this.hueD) + hueOff;
		const clr = color(hue % 360, ~~random(99), 75, 0.1);
		fill(clr); 
		// stroke(lerpColor(clr, color("#FFFFFF5F"), 0.75)); // lighten outline
		noStroke()
		rect(0, 0, d+d, random(d/50, d/3))
		pop();
	} // overlays

}


// === Tab: BgFg ===
class BgFg {

	constructor(x, y, d, t = 0.1) {
		this.x = x;
		this.y = y;
		this.d = d;
		this.t = t; // transperancy
		this.init();
	}

	init() {
		this.hueS = random(360);
		this.hueD = random(120, 210);
	}

	draw() {
		push();
		rectMode(CENTER)
		colorMode(HSB);
		translate(this.x, this.y)

		stroke("silver")
		strokeWeight(2);
		noFill();

		var d = this.d;
		circle(0, 0, d);

		// mask the circle
		beginClip();
		circle(0, 0, d);
		endClip();


		var a = random(TWO_PI)
		var r = random(d/2)
		var x = cos(a) * r
		var y = sin(a) * r

		var v = createVector(x, y).rotate(HALF_PI)

		// line(x, y, x+v.x, y+v.y)
		// line(x, y, x-v.x, y-v.y)
		push()
		strokeWeight(1)
		translate(x, y)
		rotate(v.heading())
		var hue = this.hueS + random(this.hueD/4, this.hueD)
		var clr = color(hue % 360, 75, 75, this.t);
		fill(clr); 
		// stroke(lerpColor(clr, color("#FFFFFF5F"), 0.75)); // lighten outline
		noStroke()
		rect(0, 0, d+d, random(d/50, d/3))
		pop();

		pop();
	}
}


