let gems, bgfgs;

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("grid of gems of different shape and color")
	frameRate(25);

	const DIA = ~~(max(width, height) * 0.6)

	bgfgs = [];
	bgfgs.push(new BgFg(width/2, height/2, width+height, 0.01));
	bgfgs.push(new BgFg(width/2, height/3, DIA, 0.15));

	gems = [];
	const num = ~~random(1, 5);
	for (let i = 0; i < num; i++) {
		var a = map(i, 0, num-1, random(0.5, 1), PI-random(0.5, 1));
		var x = width/2 + cos(a) * DIA/2;
		var y = height/3 + sin(a) * DIA/2;
		gems.push(new Gem(x, y + height/4 + 10, height/5, {x, y}));
	}

	background("rgb(4, 2, 12)");
}

function draw() {
	// init bg or shape colors
	if (frameCount % 100 === 0) {
		setup(); 
		return;
	}
	// pause progress last half
	if (frameCount % 100 > 50) return;

	// draw shapes / progress
	for (let bgfg of bgfgs) bgfg.draw();
	for (let gem of gems) gem.draw();
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}
